"""
Generic line-based file parser using a compiled regex with named groups.

Parses a file line by line; for each line that matches the pattern, yields
a dict with the named group captures plus "raw_line" and "line_number" (1-based).

The regex pattern MUST use named groups, e.g. (?P<name>...).
"""
from __future__ import annotations

import re
from pathlib import Path
from typing import Iterator


def parse_file(
    file_path: str | Path,
    pattern: str | re.Pattern,
) -> list[dict]:
    """
    Parse a file with a regex that uses named groups.

    Compiles the pattern (if str), then scans every line. Each match produces
    one result: a dict with all named group values plus "raw_line".

    Args:
        file_path: Path to the file to parse.
        pattern: Regex pattern (string or compiled). Must contain named groups
                 e.g. r"(?P<key>\\w+)=(?P<value>\\S+)".

    Returns:
        List of dicts. Each dict has keys from the regex named groups plus
        "raw_line" (the full line that matched) and "line_number" (1-based).

    Example:
        >>> results = parse_file("log.txt", r"(?P<time>\\d+:\\d+)\\s+(?P<msg>.+)")
        >>> for r in results:
        ...     print(r["line_number"], r["time"], r["msg"], r["raw_line"])
    """
    return list(parse_file_iter(file_path, pattern))


def parse_file_iter(
    file_path: str | Path,
    pattern: str | re.Pattern,
) -> Iterator[dict]:
    """
    Same as parse_file but yields results one by one (generator).
    Each result includes "line_number" (1-based).
    """
    if isinstance(pattern, str):
        pattern = re.compile(pattern)
    path = Path(file_path)
    with path.open(encoding="utf-8", errors="replace") as f:
        for line_number, line in enumerate(f, start=1):
            line = line.rstrip("\n\r")
            m = pattern.search(line)
            if m is not None:
                row = dict(m.groupdict())
                row["raw_line"] = line
                row["line_number"] = line_number
                yield row
